#include "test.h"
#include <xmqtt/session_image.h>
#include "../examples/common/session_peer.h"
static const void* micResult(xfuture* F)
{testRequire(F&&xrtFutureWaitFor(F,10000)==XWAIT_OK&&xrtFutureState(F)==XFUTURE_RESOLVED,"image Client typed result");return xrtFutureValue(F);}
static xmqttclient* micConnect(mqttResumePeer* P,xmqttsession* S,xmqttclientinbox* I,xfuture** Ready)
{
    xmqttclientconfig K;xmqttClientConfigInit(&K);K.Version=P->Version;xmqttpacket Q;xmqttPacketInit(XMQTT_PACKET_CONNECT,&Q);Q.Body.Connect.ClientId=XRT_STR_LITERAL("session-client");Q.Body.Connect.CleanStart=false;xmqttproperty Expiry=mqttResumeNumber(XMQTT_PROPERTY_SESSION_EXPIRY,60);if(P->Version==XMQTT_VERSION_5)Q.Properties=(xmqttpropertylist){&Expiry,1};xmqttclient* C=NULL;testRequire(xmqttClientConnectSession(P->Engine,&P->Address,1,&K,S,I,&Q,&C),"Client consumes restored ordinary Session");*Ready=xmqttClientReady(C);testRequire(((const xmqttreadyresult*)micResult(*Ready))->Status==XMQTT_STATUS_OK,"fresh image Client CONNACK");return C;
}
static void micClaim(xmqttsession* S,xmqttsessionimageconfig* Image)
{unsigned char Bytes[512];memset(Bytes,0xa5,sizeof(Bytes));size_t N=123;testRequire(xmqttSessionImageSize(S,Image,&N)==XMQTT_SESSION_STATE_ERROR&&N==123&&xmqttSessionImageWrite(S,Image,Bytes,sizeof(Bytes),&N)==XMQTT_SESSION_STATE_ERROR&&Bytes[0]==0xa5&&N==123,"live Client claim refuses passive image without mutation");xrtClearError();}
static void micCase(xmqttversion V,unsigned Phase)
{
    xmqttsessionconfig K;xmqttSessionConfigInit(&K);K.Version=V;K.ClientId=XRT_STR_LITERAL("session-client");xmqttsession* S=NULL;testRequire(xmqttSessionCreate(&K,&S),"live image source Session");xmqttclientinboxconfig IC;xmqttClientInboxConfigInit(&IC);IC.Version=V;xmqttclientinbox* I=NULL;testRequire(xmqttClientInboxCreate(&IC,&I),"separate volatile Inbox owner");mqttResumePeer P;mqttResumeStart(&P,V,Phase==0?MQTT_RESUME_HOLD_ACK:Phase==1?MQTT_RESUME_HOLD_REC:MQTT_RESUME_HOLD_COMP,false);xfuture *OldReady=NULL,*Ready=NULL,*Old=NULL;xmqttclient* C=micConnect(&P,S,I,&OldReady);
    xmqttsessionimageconfig Image;xmqttSessionImageConfigInit(&Image);Image.Binding=XRT_BYTES_LITERAL("local literal peer/principal");Image.MonotonicTime=xrtTimer();Image.WallMilliseconds=1000000;micClaim(S,&Image);
    xmqttpacket Q;xmqttPacketInit(XMQTT_PACKET_PUBLISH,&Q);Q.Flags=Phase?4:2;Q.Identifier=23;Q.Body.Publish.Topic=XRT_STR_LITERAL("recover/topic");Q.Body.Publish.Payload=XRT_BYTES_LITERAL("retained payload");testRequire(xmqttClientPublishAsync(C,&Q,10000,&Old)==XMQTT_ADMISSION_ACCEPTED,"real native outstanding publication");mqttResumeWait(Phase==2?&P.Releases:&P.Publishes,1);
    testRequire(xmqttClientClose(C)&&xmqttClientWaitFor(C,10000)==XWAIT_OK,"old native physical Client completion");Image.MonotonicTime=xrtTimer();micClaim(S,&Image);testRequire(xmqttClientDestroy(C),"old Client destruction returns exclusive Session claim");mqttResumeStop(&P);const xmqttwriteresult* W=micResult(Old);testRequire(W->Status!=XMQTT_STATUS_OK&&W->Delivery==XMQTT_MAY_HAVE_REACHED_PEER&&W->AcceptedBytes,"old uncertain outcome remains original");
    unsigned char Data[4096];size_t N=0;Image.MonotonicTime=xrtTimer();testRequire(xmqttSessionImageWrite(S,&Image,Data,sizeof(Data),&N)==XMQTT_SESSION_DONE&&xmqttSessionDestroy(S),"checkpoint after real native owners retired");S=NULL;Image.MonotonicTime=xrtTimer();testRequire(xmqttSessionImageRestore(&K,&Image,(xbytesview){Data,N},&S)==XMQTT_SESSION_DONE,"fresh state restored after original Session destruction");memset(Data,0xcc,sizeof(Data));mqttResumeStart(&P,V,0,true);C=micConnect(&P,S,I,&Ready);double End=xrtTimer()+10;xmqttsessioninfo SI;
    do{testRequire(xmqttSessionInfo(S,&SI)&&xrtTimer()<End,"actual image protocol recovery deadline");if(SI.ActiveOutgoing||SI.Objects)xrtSleep(1);}while(SI.ActiveOutgoing||SI.Objects);
    if(Phase==2){mqttResumeWait(&P.Releases,1);testRequire(!xrtAtomic32Load(&P.Publishes,XMEMORY_ACQUIRE)&&xrtAtomic32Load(&P.Releases,XMEMORY_ACQUIRE)==1,"restored actual peer sees PUBREL only");}
    else{mqttResumeWait(&P.Publishes,1);testRequire(P.Log[0].Id==23&&(P.Log[0].Flags&8u)&&P.Log[0].Topic==13&&P.Log[0].Payload==16&&!P.Log[0].Alias,"restored actual peer sees canonical original id/DUP/topic/payload");}
    testRequire(xmqttClientClose(C)&&xmqttClientWaitFor(C,10000)==XWAIT_OK&&xmqttClientDestroy(C),"restored native Client joins");mqttResumeStop(&P);testRequire(xmqttSessionDestroy(S)&&xmqttClientInboxDestroy(I),"both image state and separate Inbox physically retired");testRequire(W==xrtFutureValue(Old)&&W->Status!=XMQTT_STATUS_OK&&W->Delivery==XMQTT_MAY_HAVE_REACHED_PEER,"old result immutable past original/restored Session/Client/Engine joins");xrtFutureDestroy(Old);xrtFutureDestroy(OldReady);xrtFutureDestroy(Ready);
}
int main(void){for(unsigned V=0;V<2;++V)for(unsigned Phase=0;Phase<3;++Phase)micCase(V?XMQTT_VERSION_311:XMQTT_VERSION_5,Phase);puts("[PASS] actual Client claim/retirement and image replacement QoS1/2 ACK-cut recovery on both versions");return 0;}
